#include <bits/stdc++.h>
#define int long long
using namespace std;
int OP,t;
int n,D;
int a[2000005];
int far[2000005],fal[2000005];
int szl[2000005],szr[2000005];
void clear(){
	for(int i=0;i<=n+1;++i) a[i]=far[i]=fal[i]=szl[i]=szr[i]=0;
}
signed main(){
	freopen("migrate.in","r",stdin);
	freopen("migrate.out","w",stdout);
	scanf("%lld%lld",&OP,&t);
	while(t--){
		scanf("%lld%lld",&n,&D);
		for(int i=1;i<=n;++i) scanf("%lld",&a[i]);
		fal[1]=1;
		for(int i=2,j=1;i<=n;++i){
			while(a[i]-a[j]>D) ++j;
			fal[i]=j;
		}
		far[n]=n;
		for(int i=n-1,j=n;i;--i){
			while(a[j]-a[i]>D) --j;
			far[i]=j;
		}
		for(int i=1;i<=n;++i){
			szl[i]+=1;
			if(far[i]>i){
				if(far[far[i]-1]!=far[far[i]]){
					szl[far[i]]+=szl[i];
				}
			}
		}
		for(int i=1;i<=n;++i){
			if(far[i]>i){
				if(far[far[i]-1]==far[far[i]]) szl[far[i]]+=1;
			}
		}
		for(int i=n;i;--i){
			szr[i]+=1;
			if(fal[i]<i){
				if(fal[fal[i]+1]!=fal[fal[i]]){
					// cerr<<"ok "<<i<<"-> "<<fal[fal[i]]<<"\n";
					szr[fal[i]]+=szr[i];
				}
			}
		}
		for(int i=n;i;--i){
			if(fal[i]<i){
				if(fal[fal[i]+1]==fal[fal[i]]) szr[fal[i]]+=1;
			}
		}
		// for(int i=1;i<=n;++i) cerr<<szl[i]<<" ";cerr<<"\n";
		// for(int i=1;i<=n;++i) cerr<<szr[i]<<" ";cerr<<"\n";
		// for(int i=1;i<=n;++i) szl[i]+=szl[i-1];
		// for(int i=n;i;--i) szr[i]+=szr[i+1];
		int ans=0;
		for(int i=2;i+1<n;++i){
			int lbl=fal[i+1],rbl=fal[i+2]-1;
			rbl=min(rbl,i-1);
			if(lbl>rbl) continue;
			int rbr=far[i],lbr=far[i-1]+1;
			lbr=max(lbr,i+2);
			if(lbr>rbr) continue;
			// cerr<<"i="<<i<<"  ["<<lbl<<","<<rbl<<"]  ["<<lbr<<","<<rbr<<"]\n";
			int cl=rbl-lbl+1;
			int cr=rbr-lbr+1;
			if(fal[i]==lbl) cl+=szl[lbl]-1;
			if(far[i+1]==rbr) cr+=szr[rbr]-1;
			// cerr<<"  cl="<<cl<<" cr="<<cr<<"\n";
			ans+=cl*cr;
		}
		printf("%lld\n",ans);
		clear();
	}
	return 0;
}
